//
// The near-field table (near_field_table.c, generated by
// tools/near_field_table.py): a rigid sphere's response to a point source
// over its response to one at infinity, per ear, as a DC gain and an
// analog first-order high shelf H(s) = (V s + w) / (s + w).

#ifndef MAUL_AUDIO_SRC_NEAR_FIELD_TABLE_H
#define MAUL_AUDIO_SRC_NEAR_FIELD_TABLE_H

// Incidence angles 0 to 180 degrees, 5 apart: the angle at the head's
// centre between the ear and the source.
#define MAUD_NEAR_FIELD_ANGLES    37
#define MAUD_NEAR_FIELD_DISTANCES 24

// Inverse normalized distances, the head radius over the source's
// distance, rising from 0 (a source at infinity) to 1 / 1.15.
extern const float maudNearFieldInverseDistances[MAUD_NEAR_FIELD_DISTANCES];

// Per angle and distance: the DC gain in dB, the shelf's high-frequency
// gain V in dB, and the natural log of its corner w in normalized
// frequency (2 pi f a / c, a the head radius).
extern const float maudNearFieldTable[MAUD_NEAR_FIELD_ANGLES][MAUD_NEAR_FIELD_DISTANCES][3];

#endif // MAUL_AUDIO_SRC_NEAR_FIELD_TABLE_H
